#!/usr/bin/env python3
"""Run drive.py and show output with escapes rendered readable."""
import subprocess, sys, os

def render(b: bytes) -> str:
    s = b.decode('utf-8', errors='replace')
    out = []
    i = 0
    while i < len(s):
        c = s[i]
        if c == '\x1b':
            # find end of sequence
            j = i+1
            if j < len(s) and s[j] == '[':
                j += 1
                while j < len(s) and not (0x40 <= ord(s[j]) <= 0x7e):
                    j += 1
                j += 1
                out.append('«' + s[i:j].replace('\x1b','E') + '»')
                i = j
            elif j < len(s) and s[j] == 'P':
                j += 1
                while j < len(s) and s[j:j+2] != '\x1b\\':
                    j += 1
                j += 2
                out.append('«' + s[i:j].replace('\x1b','E') + '»')
                i = j
            else:
                out.append('«E»')
                i += 1
        elif c == '\0':
            out.append('«NUL»')
            i += 1
        elif c == '\r':
            out.append('«CR»')
            i += 1
        else:
            out.append(c)
            i += 1
    return ''.join(out)

if __name__ == '__main__':
    p = subprocess.run(['python3', os.path.join(os.path.dirname(__file__), 'drive.py')] + sys.argv[1:],
                       capture_output=True)
    sys.stdout.write(render(p.stdout))
    if p.stderr:
        sys.stderr.write(p.stderr.decode())

